#!/usr/bin/env bash
# The label maker's base photos (SC-147): blank stickers on cartons, in the angles and light a distributor's phone photo
# can have, rendered by the local Qwen-Image model (the qwengen-bf16 plugin's CLI), one at a time, into src/ (git-ignored).
# `python3 make.py bases` then finds each sticker and writes bases/*.webp with bases.json. Run it in the background:
#   nohup design3/system/labels/bases.sh > design3/system/labels/src/bases.log 2>&1 &
set -u
cd "$(dirname "$0")"
mkdir -p src
PY="$HOME/qwen-image-bf16/.venv/bin/python"
GEN="$HOME/.claude/plugins/cache/qwen-bf16-local/qwen-image-bf16/0.2.0/server/qwen_image_bf16_mac.py"
gen() { [ -f "src/base-$1.png" ] || "$PY" "$GEN" "$2" --aspect 4:3 --size 1024 --seed "$1" --out "src/base-$1.png"; }
gen 14701 "A realistic close-up smartphone photo of a plain blank white rectangular paper label sticker stuck flat on the side of a brown corrugated cardboard carton, the label fills most of the frame with a margin of brown cardboard visible on every side, nothing printed on the label, the label slightly glossy with tiny creases at one corner, even daylight from a godown window, the camera square on to the carton, sharp focus, natural colours."
gen 14710 "A close-up photo of a blank white rectangular paper label stuck on the side of a brown corrugated carton on a godown shelf, the camera slightly to the left so the label recedes a little to the right, cool tube light from above, other cartons blurred behind. nothing printed on the label, plain matte white paper with a thin glossy sheen, every corner of the label visible with brown cardboard all round it, realistic smartphone photo, sharp focus on the label, natural colours."
